 * MboxMsgInputStream implementation.
 */

NS_IMPL_ISUPPORTS(MboxMsgInputStream, nsIInputStream);

MboxMsgInputStream::MboxMsgInputStream(nsIInputStream* mboxStream,
                                       uint32_t maxAllowedSize)
    : mRawStream(mboxStream),
      mStatus(NS_OK),
      mBuf(8192),
      mUsed(0),
      mUnused(0),
      mTotalUsed(0),
      mMsgOffset(0),
      mLimitOutputBytes(maxAllowedSize),
      mOutputBytes(0),
      mOverflow(false),
      mParser(new MboxParser()),
      mLock("MboxMsgInputStream.mLock") {
  // Ensure the first chunk is read and parsed.
  // This should include the "From " line, so EnvAddr()/EnvDate()
  // can be used right away.
  mStatus = PumpData();
}

MboxMsgInputStream::~MboxMsgInputStream() { Close(); }

NS_IMETHODIMP MboxMsgInputStream::Close() {
  MutexAutoLock lock(mLock);
  mRawStream->Close();
  mStatus = NS_BASE_STREAM_CLOSED;
  return NS_OK;
}

bool MboxMsgInputStream::IsNullMessage() {
  MutexAutoLock lock(mLock);
  return mParser->IsFinished() && (mMsgOffset == mTotalUsed);
}

nsresult MboxMsgInputStream::Continue(bool& more) {
  MutexAutoLock lock(mLock);
  more = false;

  // Can't continue if the stream was closed.
  if (mStatus == NS_BASE_STREAM_CLOSED) {
    return NS_BASE_STREAM_CLOSED;
  }

  MOZ_ASSERT(NS_SUCCEEDED(mStatus));
  MOZ_ASSERT(mParser->IsFinished());
  // Record start of the next message (or EOF).
  mMsgOffset = mTotalUsed;

  // Tell the parser to start on the next message
  mParser->Kick();
  mStatus = PumpData();
  if (NS_FAILED(mStatus)) {
    return mStatus;
  }
  if (mParser->AtEOF()) {
    // No more messages.
    return NS_OK;
  }

  more = true;
  return NS_OK;
}

nsCString MboxMsgInputStream::EnvAddr() {
  MutexAutoLock lock(mLock);
  return mParser->EnvAddr();
}

PRTime MboxMsgInputStream::EnvDate() {
  MutexAutoLock lock(mLock);
  return mParser->EnvDate();
}

uint64_t MboxMsgInputStream::MsgOffset() {
  MutexAutoLock lock(mLock);
  return mMsgOffset;
}

// Throw NS_BASE_STREAM_CLOSED if closed.
// Return 0 if EOF but not closed.
// Else return available bytes.
NS_IMETHODIMP MboxMsgInputStream::Available(uint64_t* result) {
  MutexAutoLock lock(mLock);
  *result = 0;
  if (NS_FAILED(mStatus)) {
    return mStatus;
  }
  mStatus = PumpData();
  *result = static_cast<uint64_t>(mParser->Available());
  return mStatus;
}

NS_IMETHODIMP MboxMsgInputStream::StreamStatus() {
  MutexAutoLock lock(mLock);
  return mStatus;
}

// Returns a count, or 0 if EOF or closed.
// Never throws NS_BASE_STREAM_CLOSED
NS_IMETHODIMP MboxMsgInputStream::Read(char* buf, uint32_t count,
                                       uint32_t* result) {
  MutexAutoLock lock(mLock);
  *result = 0;
  if (mOverflow) {
    // Calling trivial glean function while holding the lock should be ok.
    mozilla::glean::mail::mbox_read_errors.Get("unexpected_size"_ns).Add(1);
    return NS_MSG_ERROR_UNEXPECTED_SIZE;
  }
  if (mStatus == NS_BASE_STREAM_CLOSED) {
    return NS_OK;
  }
  if (NS_FAILED(mStatus)) {
    return mStatus;
  }

  // We just keep feeding data into the parser and copying out its output.
  while (count > 0 && !mOverflow) {
    mStatus = PumpData();
    if (NS_FAILED(mStatus)) {
      return mStatus;
    }
    size_t n = mParser->Drain(buf, (size_t)count);
    if (n == 0) {
      break;  // Nothing more in this message. Return EOF.
    }
    MOZ_ASSERT(n <= UINT32_MAX);

    const size_t use =
        !mLimitOutputBytes
            ? n
            : std::min(n, (size_t)(mLimitOutputBytes - mOutputBytes));

    if (use < n) {
      // We want the current read to return success (because we're
      // returning up to the requested amount of bytes),
      // but future calls to Read() should return failure.
      mOverflow = true;
    }

    mOutputBytes += use;

    buf += use;
    count -= (uint32_t)use;
    *result += use;
  }
  return NS_OK;
}

